const NAV=[['resumen','Resumen','home'],['oficina','Oficina virtual','office'],['clientes','Clientes','people'],['cotizar','Cotizar','calculator'],['cotizaciones','Cotizaciones','document'],['financieras','Solicitudes','bank'],['inventario','Motos y precios','bike'],['fichas','Fichas técnicas','image'],['mensajes','Mensajes','chat'],['posventa','Posventa','wrench'],['reportes','Ventas y comisiones','chart'],['ajustes','Respaldo y ajustes','settings']];
