PATHS.office='m3 8 9-5 9 5v9l-9 5-9-5zM3 8l9 5 9-5M12 13v9M7 6l10 6';
PATHS.image='M4 3h16a1 1 0 0 1 1 1v16a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1m-1 13 5-5 4 4 3-3 6 6M8 8h.01';
PATHS.copy='M9 9h11v12H9zM5 15H3V3h12v2';
