function saveQuote(){
 const selected=stock(ui.quoteStockId);if(!selected){toast('Seleccioná la moto de la cotización.',true);return;}
 const validUntil=$('quote-valid-until')?.value||addDays(today(),db.settings.validDays);
 if(!validUntil||validUntil<today()){toast('La fecha de validez debe ser hoy o una fecha posterior.',true);return;}
 const note=($('quote-note')?.value||'').trim();const snapshot=api?.snapshot();
 if(ui.quoteMode==='credit'&&(!snapshot?.complete)){toast('Completá una cotización disponible antes de guardarla.',true);return;}
 const cashState=ui.quoteMode==='cash'?cashSnapshot():null;if(cashState&&!cashState.valid){toast(cashState.error,true);return;}const cash=cashState?cashState.amounts.totalCents/100:0;
 const next=clone(db),prefix='COT-'+today().replaceAll('-','')+'-';let serial=1;while(next.quotes.some(q=>q.number===prefix+String(serial).padStart(3,'0')))serial++;
 const q={id:uid(),number:prefix+String(serial).padStart(3,'0'),date:today(),createdAt:new Date().toISOString(),validUntil,clientId:ui.quoteClientId,customerName:client(ui.quoteClientId)?.name||'',customerPhone:client(ui.quoteClientId)?.phone||'',stockId:selected.id,modelLabel:selected.label+(selected.year?' · '+selected.year:''),calcModelId:selected.calcModelId,mode:ui.quoteMode,price:ui.quoteMode==='credit'?snapshot.quote.price:cash,financierName:ui.quoteMode==='credit'?snapshot.quote.financierName:'Contado',calcState:ui.quoteMode==='credit'?snapshot.state:null,calculation:ui.quoteMode==='credit'?snapshot.quote:null,sourceText:ui.quoteMode==='credit'?snapshot.text:'Cotización de contado. '+note,note,status:'Pendiente',advisor:db.settings.advisor,agency:db.settings.agency,advisorPhone:db.settings.phone,location:db.settings.location};
 if(cashState){q.cashData=cashDataForSave(cashState);q.customerName=cashState.customerName;q.modelLabel=selected.label+(cashState.year?' · '+cashState.year:'');q.sourceText=quoteMessage(q);}
 next.quotes.push(q);const c=next.clients.find(c=>c.id===q.clientId);if(c){eventFor(c,'Cotización '+q.number+' guardada · '+q.modelLabel);if(c.stage==='Nuevo')c.stage='Contactado';if(!c.stockId)c.stockId=q.stockId;}
 if(commit(next,'Cotización guardada'))viewQuote(q.id);
}
function quoteEntries(q){if(q.mode==='cash'){const d=q.cashData;return d?[['Precio al contado',money(d.basePrice)],...(d.discountAmount>0?[['Descuento','− '+money(d.discountAmount)]]:[]),...(d.extraAmount>0?[[d.extraLabel||'Gastos adicionales',money(d.extraAmount)]]:[]),['Total a pagar',money(q.price)]]:[['Precio de contado',money(q.price)]];}const c=q.calculation;return [['Precio de la moto',money(c.price)],['Prima inicial',money(c.downAmount)],['Gastos administrativos',money(c.fee)],['Pago inicial total',money(c.initialPayment)],['Monto a financiar',money(c.principal)],...(q.calcState?.detailsVisible!==false?[['Intereses y ajustes estimados',money(c.selected.interest)],['Total estimado, incluida prima y gastos',money(c.selected.total)]]:[])];}
function quotePlan(q){if(q.mode==='cash')return 'Contado';const c=q.calculation;return [q.financierName,c.plan?.name||c.profile?.name||'',c.estimated?'Estimación':''].filter(Boolean).join(' · ');}
function quoteConditions(q){const c=q.calculation;return [q.note,q.mode==='credit'?(c.sourceNote||'Cotización referencial. Los gastos se muestran por separado y no se incluyen en las cuotas. El último pago puede ajustarse por redondeo.'):'Precio de contado según la propuesta indicada.',q.mode==='credit'?'Sujeta a evaluación y condiciones de la financiera.':'',demo?'EJEMPLO FICTICIO · NO ES UNA OFERTA COMERCIAL.':''].filter(Boolean).join('\n');}
function quoteHTML(q){const photo=photoForQuote(q);return `<article class="quote-document"><div class="document-top"><div><h3>Cotización ${q.mode==='cash'?'de contado':'de crédito'}</h3><p>${esc(q.number)} · ${esc(fmtDate(q.date))}</p></div>${logo?`<img src="${logo}" alt="TVS">`:`<strong>TVS</strong>`}</div><div class="document-customer"><div><small>PREPARADA PARA</small><strong>${esc(q.customerName||'Cliente')}</strong>${q.customerPhone?'<br>'+esc(q.customerPhone):''}</div><div><small>VÁLIDA HASTA</small>${esc(fmtDate(q.validUntil))}</div></div><div class="document-model">${photo?`<img src="${photo}" alt="${esc(q.modelLabel)}">`:''}<div><h3>TVS ${esc(q.modelLabel)}</h3><p class="subtext">${esc(quotePlan(q))}</p></div></div><div class="document-payment"><span>${q.mode==='cash'?(q.cashData?'Total a pagar':'Precio de contado'):`${q.calculation.selected.months} cuotas mensuales de`}<small>${q.mode==='cash'?'Pago de contado':'Pago inicial total: '+money(q.calculation.initialPayment)}</small></span><strong>${money(q.mode==='cash'?q.price:q.calculation.selected.monthly)}</strong></div><table class="document-table"><tbody>${quoteEntries(q).map(([l,v])=>`<tr><td>${esc(l)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table>${q.mode==='cash'?cashSavedDetails(q):''}<p class="document-notes">${esc(quoteConditions(q))}</p><div class="document-signature"><strong>${esc(q.advisor)} · ${esc(q.agency)}</strong><br>${esc([q.advisorPhone,q.location].filter(Boolean).join(' · '))}</div></article>`;}
function quoteMessage(q){if(q.mode==='cash'&&q.cashData){const d=q.cashData;return ['COTIZACIÓN AL CONTADO',q.modelLabel,q.customerName?'Preparada para: '+q.customerName:'',d.color?'Color: '+d.color:'',...quoteEntries(q).map(([label,value])=>label+': '+value),d.showSpecs!==false?(d.specs||[]).map(row=>row.label+': '+row.value).join('\n'):'',d.benefits?'Incluye: '+d.benefits:'',d.showDates!==false?'Válida hasta: '+fmtDate(q.validUntil):'',q.note,q.advisor+' · '+q.agency].filter(Boolean).join('\n\n');}return [q.customerName?'Hola, '+q.customerName+'.':'Hola.',q.mode==='cash'?'Te comparto tu cotización de contado.':'Te comparto la opción de financiamiento para tu moto.',q.modelLabel,q.mode==='cash'?'Precio de contado: '+money(q.price):['Financiera: '+q.financierName,'Pago inicial total: '+money(q.calculation.initialPayment),'Cuota: '+money(q.calculation.selected.monthly),'Plazo: '+q.calculation.selected.months+' meses'].join('\n'),'Válida hasta: '+fmtDate(q.validUntil),quoteConditions(q),q.advisor+' · '+q.agency].join('\n\n');}
