const TEMPLATES={seguimiento:['Seguimiento','Retomá una consulta pendiente'],documentos:['Pedir documentos','Indicá qué hace falta'],preaprobado:['Preaprobación','Avisá el siguiente paso'],visita:['Invitar a la agencia','Coordiná una visita'],contado:['Crédito y contado','Explicá las modalidades'],posventa:['Después de la entrega','Mantené el contacto']};
function makeMessage(type,c){const name=c?.name||'[nombre]',model=stock(c?.stockId)?.label||'[modelo]',advisor=db.settings.advisor,agency=db.settings.agency;
 const base={seguimiento:`Hola, ${name}. Te saluda ${advisor} de ${agency}. Quería dar seguimiento a tu consulta por la ${model}. ¿Seguís interesado o hay alguna duda en la que te pueda ayudar?`,documentos:`Hola, ${name}. Para continuar con la gestión de tu ${model}, nos hace falta recibir: [documentos pendientes]. Cuando los tengás, podés compartirlos para completar la solicitud. Quedo pendiente. ${advisor} · ${agency}.`,preaprobado:`Hola, ${name}. Te saluda ${advisor} de ${agency}. La financiera nos informó que tu solicitud está preaprobada. El siguiente paso es [completar documentación / confirmar condiciones]. La aprobación final y las condiciones quedan sujetas a la revisión de la financiera.`,visita:`Hola, ${name}. Te invito a conocer la ${model} en ${agency}. Podemos revisar las opciones de contado o crédito y resolver tus dudas. ¿Qué día te queda bien visitarnos? Te atiende ${advisor}.`,contado:`Hola, ${name}. Podemos cotizarte la ${model} de contado o al crédito. En crédito, el monto final depende de la prima, el plazo, los intereses y los cargos de la financiera. Te puedo preparar ambas opciones para que elijás la que mejor te convenga. ${advisor} · ${agency}.`,posventa:`Hola, ${name}. Soy ${advisor} de ${agency}. Quería saber cómo te ha ido con tu ${model} y si tenés alguna consulta después de la entrega. También podemos revisar cuándo corresponde tu próximo mantenimiento, según el manual y lo indicado por el taller.`};return base[type]||base.seguimiento;}
function renderMessages(){const selected=client(ui.messageClientId);$('view-mensajes').innerHTML=heading('Mensajes listos para adaptar','Elegí al cliente, revisá el texto y copialo a tu conversación.')+`<div class="two-col"><div class="card"><div class="card-head"><h2>Elegí el motivo</h2></div><div class="card-body"><div class="message-templates">${Object.entries(TEMPLATES).map(([id,[name,desc]])=>`<button class="template-button${ui.template===id?' active':''}" data-action="choose-template" data-id="${id}">${esc(name)}<small>${esc(desc)}</small></button>`).join('')}</div></div></div><div class="card"><div class="card-head"><h2>Tu mensaje</h2>${badge('Editable')}</div><div class="card-body"><div class="field" style="margin-bottom:17px"><label for="message-client">Cliente</label><select id="message-client">${clientOptions(ui.messageClientId,'Sin seleccionar')}</select></div><textarea class="message-editor" id="message-text" aria-label="Mensaje para el cliente">${esc(makeMessage(ui.template,selected))}</textarea><div class="row-actions" style="margin-top:16px">${button('Copiar mensaje','copy-message','',true)}${button('Abrir WhatsApp','open-whatsapp')}</div><p class="subtext" style="margin-top:13px">Revisá y completá los campos entre corchetes antes de enviarlo.</p></div></div></div>`;}
function renderPostSales(){const list=[...db.postSales].sort((a,b)=>Number(a.done)-Number(b.done)||(a.nextDate||'9999').localeCompare(b.nextDate||'9999'));$('view-posventa').innerHTML=heading('Después de la entrega','Programá el contacto y las revisiones acordadas con tu cliente.',button('+ Agregar seguimiento','new-postsale','',true))+`<div class="card table-wrap">${list.length?`<table><thead><tr><th>Cliente y moto</th><th>Entrega</th><th>Próximo contacto / revisión</th><th>Estado</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(client(p.clientId)?.name||'Cliente')}</strong><small>${esc(stock(p.stockId)?.label||'Moto por definir')}</small></td><td>${esc(fmtDate(p.delivery))}</td><td>${esc(fmtDate(p.nextDate))}<small>${esc(p.notes.slice(0,70))}</small></td><td>${badge(p.done?'Realizado':p.nextDate&&p.nextDate<today()?'Vencido':'Pendiente',p.done?'green':p.nextDate&&p.nextDate<today()?'red':'amber')}</td><td><div class="table-actions">${button('Editar','edit-postsale',p.id)}${!p.done?button('Realizado','complete-postsale',p.id):''}</div></td></tr>`).join('')}</tbody></table>`:empty('Seguimiento desde la primera entrega','Agendá la fecha que corresponda según lo acordado y el manual de la moto.',button('Agregar seguimiento','new-postsale','',true))}</div>`;}
function renderReports(){
 const sales=db.sales.filter(s=>s.date.startsWith(ui.reportMonth)),campaigns=db.campaigns.filter(c=>c.date.startsWith(ui.reportMonth)),revenue=sales.reduce((n,s)=>n+s.amount,0),spend=campaigns.reduce((n,c)=>n+c.spend,0),commission=sales.reduce((n,s)=>n+s.commission,0);
 $('view-reportes').innerHTML=heading('Ventas y publicidad','Mirá tus resultados con ventas e inversiones que hayas registrado.',button('+ Campaña','new-campaign')+button('+ Registrar venta','new-sale','',true))+`<div class="toolbar"><label class="subtext" for="report-month">Mes del reporte</label><input style="width:175px" type="month" id="report-month" value="${ui.reportMonth}"><span style="flex:1"></span>${button('Exportar ventas CSV','export-sales')}</div><div class="metrics">${metric('Ventas registradas',sales.length,'Entregas del mes seleccionado','bike')}${metric('Monto vendido',money(revenue),'Suma de precios de venta','chart')}${metric('Inversión publicitaria',money(spend),'Campañas del mes','chat')}${metric('Comisiones registradas',money(commission),'Importes ingresados por vos','document')}</div><div class="card"><div class="card-head"><h2>Campañas y resultados</h2><span class="subtext">Las ventas se atribuyen al registrar su campaña.</span></div><div class="table-wrap">${campaigns.length?`<table><thead><tr><th>Campaña</th><th>Inversión</th><th>Consultas</th><th>Ventas atribuidas</th><th>Costo por venta</th><th></th></tr></thead><tbody>${campaigns.map(c=>{const count=db.sales.filter(s=>s.campaignId===c.id).length;return `<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.channel)} · ${esc(fmtDate(c.date))}</small></td><td>${money(c.spend)}</td><td>${num(c.consultations)}</td><td>${count}</td><td>${count?money(c.spend/count):'—'}</td><td><div class="table-actions">${button('Editar','edit-campaign',c.id)}</div></td></tr>`;}).join('')}</tbody></table>`:empty('Medí tu próxima pauta','Registrá la inversión, las consultas y las ventas que se originen en cada campaña.')}</div></div><div class="card" style="margin-top:22px"><div class="card-head"><h2>Ventas del mes</h2>${badge(sales.length+(sales.length===1?' venta':' ventas'),'green')}</div><div class="table-wrap">${sales.length?`<table><thead><tr><th>Cliente</th><th>Moto</th><th>Fecha</th><th>Precio de venta</th><th>Origen</th><th></th></tr></thead><tbody>${[...sales].reverse().map(s=>`<tr><td><strong>${esc(client(s.clientId)?.name||'Cliente')}</strong></td><td>${esc(stock(s.stockId)?.label||'Moto')}</td><td>${esc(fmtDate(s.date))}</td><td>${money(s.amount)}</td><td>${esc(s.source)}<small>${esc(db.campaigns.find(c=>c.id===s.campaignId)?.name||'Sin campaña atribuida')}</small></td><td><div class="table-actions">${button('Editar','edit-sale',s.id)}</div></td></tr>`).join('')}</tbody></table>`:empty('Todavía no hay ventas registradas este mes','Registrá una venta para incluirla en el reporte.')}</div></div>`;
}
function renderSettings(){const s=db.settings;$('view-ajustes').innerHTML=heading('Respaldo y ajustes','Tus datos de asesor y las copias para recuperar tu trabajo.')+`<div class="two-col"><form class="card" data-form="settings"><div class="card-head"><h2>Datos del asesor</h2></div><div class="card-body"><div class="form-grid">${field('Nombre del asesor','advisor','text',s.advisor,true)}${field('Agencia','agency','text',s.agency,true)}${field('WhatsApp del asesor','phone','tel',s.phone)}${field('Ubicación','location','text',s.location)}${field('Validez de cotización · días','validDays','number',s.validDays)}<div class="field"><label for="settings-theme">Apariencia</label><select id="settings-theme" name="theme">${options([['light','Clara'],['dark','Oscura']],s.theme)}</select></div></div><button class="btn btn-primary" type="submit" style="margin-top:22px">Guardar ajustes</button></div></form><div><div class="card"><div class="card-head"><h2>Tus respaldos</h2>${icon('download')}</div><div class="card-body"><p class="subtext">Los registros se guardan en este navegador. Exportá un respaldo para recuperarlos o moverlos a otra PC. El archivo HTML contiene la aplicación; el JSON contiene tus registros.</p><div class="inline-cards"><div class="mini-card"><span>Clientes</span><strong>${db.clients.length}</strong></div><div class="mini-card"><span>Cotizaciones</span><strong>${db.quotes.length}</strong></div></div><div class="row-actions" style="margin-top:20px">${button('Exportar respaldo JSON','export-json','',true)}${button('Importar respaldo','import-json')}</div><div class="row-actions" style="margin-top:12px">${button('Recuperar guardado anterior','recover-previous')}${storageBroken?button('Descargar datos anteriores','export-raw'):''}</div><p class="subtext" style="margin-top:16px">El cotizador anterior está conservado en el ZIP de respaldo original del 21 de octubre de 2026.</p></div></div><div class="card" style="margin-top:22px"><div class="card-head"><h2>Explorá sin llenar tu agenda</h2></div><div class="card-body"><p class="subtext">La demostración usa un espacio separado con ejemplos ficticios.</p><div class="row-actions" style="margin-top:16px">${demo?button('Volver a mis datos','exit-demo'):button('Abrir demostración','enter-demo')}</div></div></div></div></div>`;}
function field(label,name,type='text',value='',full=false,required=false){return `<div class="field${full?' full':''}"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}"${required?' required':''}${type==='number'?' min="0" step="0.01"':''}${type==='text'?' maxlength="250"':''}></div>`;}
function selectField(label,name,html,full=false){return `<div class="field${full?' full':''}"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${html}</select></div>`;}
function areaField(label,name,value='',full=true){return `<div class="field${full?' full':''}"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" maxlength="3000">${esc(value)}</textarea></div>`;}
function openModal(title,body,actions='',width=680){pdfGeneration++;if(pdfUrl){URL.revokeObjectURL(pdfUrl);pdfUrl='';}const m=$('modal');if(m.open)m.close();m.style.width=`min(${width}px,94vw)`;m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-close aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;m.showModal();}
function showCalculatorImage(blob,filename){
 if(!(blob instanceof Blob)||blob.type!=='image/png')return;
 openModal('Tu cotización como imagen','<p class="subtext" style="margin:0 0 16px;line-height:1.8">El navegador no permitió copiar automáticamente. Hacé clic derecho sobre la imagen y elegí <strong>Copiar imagen</strong>, o descargá el PNG y adjuntalo en WhatsApp.</p><div class="quote-image-output"><img id="quote-image-output" alt="Cotización con los plazos, cuotas y foto de la moto"></div>','<a class="btn" id="quote-image-original" target="_blank" rel="noopener noreferrer">Ver tamaño original ↗</a><a class="btn btn-primary" id="quote-image-download">Descargar PNG</a><button class="btn" data-close>Cerrar</button>',820);
 pdfUrl=URL.createObjectURL(blob);$('quote-image-output').src=pdfUrl;$('quote-image-original').href=pdfUrl;$('quote-image-download').href=pdfUrl;$('quote-image-download').download=filename||'Cotizacion-TVS.png';
}
function formModal(title,form,body,id=''){openModal(title,`<form id="record-form" data-form="${form}" data-id="${esc(id)}"><div id="form-error" class="form-error" hidden></div><div class="form-grid">${body}</div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn btn-primary" type="submit" form="record-form">Guardar</button>`);}
function formError(msg){const el=$('form-error');if(el){el.textContent=msg;el.hidden=false;el.scrollIntoView({block:'nearest'});}else toast(msg,true);}
function editClient(id=''){const c=client(id)||{name:'',phone:'',stockId:'',stage:'Nuevo',source:'WhatsApp',paymentMode:'Crédito',nextFollow:'',notes:''};formModal(id?'Editar cliente':'Nuevo cliente','client',field('Nombre del cliente *','name','text',c.name,false,true)+field('Teléfono / WhatsApp','phone','tel',c.phone)+selectField('Moto de interés','stockId',stockOptions(c.stockId,'Por definir'))+selectField('Estado','stage',options(STAGES,c.stage))+selectField('Origen de la consulta','source',options(SOURCES,c.source))+selectField('Modalidad','paymentMode',options(['Crédito','Contado','Por definir'],c.paymentMode))+field('Próximo seguimiento','nextFollow','date',c.nextFollow)+areaField('Notas de la conversación','notes',c.notes),id);}
function viewClient(id){const c=client(id);if(!c)return;const quotes=db.quotes.filter(q=>q.clientId===id);openModal('Ficha del cliente',`<div class="detail-header"><span class="avatar">${esc(initials(c.name))}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.phone||'Sin teléfono')} · ${esc(c.source)}</p></div></div><div class="detail-grid"><div class="detail-cell"><span>Moto de interés</span><strong>${esc(stock(c.stockId)?.label||'Por definir')}</strong></div><div class="detail-cell"><span>Estado</span>${stageBadge(c.stage)}</div><div class="detail-cell"><span>Próximo seguimiento</span><strong>${esc(fmtDate(c.nextFollow))}</strong></div><div class="detail-cell"><span>Modalidad</span><strong>${esc(c.paymentMode)}</strong></div></div>${c.notes?`<p class="section-label">Notas</p><p class="subtext" style="white-space:pre-wrap">${esc(c.notes)}</p>`:''}<div class="row-actions" style="margin-top:20px">${button('Cotizar','quote-client',id,true)}${button('Mensaje','client-message',id)}${button('Registrar solicitud','request-client',id)}${button('Registrar venta','sale-client',id)}</div><p class="section-label">Seguimiento</p><form data-form="followup" data-id="${id}"><div class="form-grid">${field('Próximo contacto','nextFollow','date',c.nextFollow)}${field('Resultado del contacto','result','text','')}</div><button class="btn btn-small" type="submit" style="margin-top:12px">Registrar contacto realizado</button></form><p class="section-label">Cotizaciones · ${quotes.length}</p>${quotes.map(q=>`<div class="info-row"><span>${esc(q.number)} · ${esc(q.financierName)}</span><button class="text-button" data-action="view-quote" data-id="${q.id}">Ver propuesta →</button></div>`).join('')||'<p class="subtext">Todavía no tiene cotizaciones guardadas.</p>'}<p class="section-label">Historial</p><ul class="timeline">${(c.history||[]).map(h=>`<li>${esc(h.text)}<small>${esc(fmtDate(h.at))}</small></li>`).join('')}</ul>`,`<button class="btn" data-action="archive-client" data-id="${id}">${c.archived?'Reactivar cliente':'Archivar cliente'}</button><button class="btn btn-primary" data-action="edit-client" data-id="${id}">Editar ficha</button>`,760);}
function editStock(id=''){const s=stock(id)||{label:'',calcModelId:'',type:'Urbana',year:'',colors:'',price:null,quantity:null,promo:'',active:true};formModal(id?'Editar modelo':'Agregar modelo','stock',field('Nombre del modelo *','label','text',s.label,true,true)+selectField('Tipo de moto','type',options(['Urbana','Deportiva','Scooter','Trabajo','Carga'],s.type))+field('Año','year','text',s.year)+field('Colores','colors','text',s.colors)+field('Unidades disponibles','quantity','number',s.quantity??'')+field('Precio vigente · USD','price','number',s.price??'')+selectField('Foto del cotizador','calcModelId',options(models.map(m=>[m.id,m.label]),s.calcModelId,'Sin foto / modelo personalizado'))+areaField('Promoción y restricciones vigentes','promo',s.promo)+`<div class="field full"><label class="check"><input type="checkbox" name="active" ${s.active!==false?'checked':''}> Disponible para nuevas cotizaciones</label><small>Dejá precio o existencias vacíos cuando estén pendientes de confirmar.</small></div>`,id);}
function editRequest(id='',clientId=''){const r=db.requests.find(r=>r.id===id)||{clientId,lender:'Crediopciones',status:'Pendiente',date:today(),expires:'',notes:'',docs:[]};if(!db.clients.length){toast('Agregá un cliente antes de registrar una solicitud.',true);editClient();return;}formModal(id?'Editar solicitud':'Nueva solicitud','request',selectField('Cliente *','clientId',clientOptions(r.clientId,'Seleccioná un cliente'))+selectField('Financiera','lender',options(LENDERS,r.lender))+selectField('Respuesta registrada','status',options(['Pendiente','Enviada','Preaprobada','Aprobada','Rechazada','Cerrada'],r.status))+field('Fecha de gestión','date','date',r.date)+field('Vence el · opcional','expires','date',r.expires)+areaField('Condiciones y observaciones recibidas','notes',r.notes)+`<div class="field full"><span class="field-label">Documentos recibidos</span><div class="checks">${r.docs.map((d,i)=>`<label class="check"><input type="checkbox" name="doc-${i}" ${d.done?'checked':''}>${esc(d.label)}</label>`).join('')||'<p class="subtext">Agregá los documentos que te pida la financiera.</p>'}</div></div>`+areaField('Agregar documentos · uno por línea','newDocs',''),id);}
function editPostSale(id='',clientId=''){const p=db.postSales.find(p=>p.id===id)||{clientId,stockId:client(clientId)?.stockId||'',delivery:today(),nextDate:'',notes:'',done:false};if(!db.clients.length){editClient();toast('Primero registrá al cliente.');return;}formModal(id?'Editar posventa':'Seguimiento de posventa','postsale',selectField('Cliente *','clientId',clientOptions(p.clientId,'Seleccioná un cliente'))+selectField('Moto','stockId',stockOptions(p.stockId))+field('Fecha de entrega','delivery','date',p.delivery)+field('Fecha de contacto / revisión','nextDate','date',p.nextDate)+areaField('Motivo y observaciones','notes',p.notes)+`<div class="field full"><label class="check"><input type="checkbox" name="done" ${p.done?'checked':''}> Seguimiento realizado</label></div>`,id);}
function editSale(id='',clientId=''){const s=db.sales.find(s=>s.id===id)||{clientId,stockId:client(clientId)?.stockId||'',amount:'',commission:'',date:today(),source:client(clientId)?.source||'WhatsApp',campaignId:'',notes:''};if(!db.clients.length){editClient();toast('Primero registrá al cliente.');return;}formModal(id?'Editar venta registrada':'Registrar venta','sale',selectField('Cliente *','clientId',clientOptions(s.clientId,'Seleccioná un cliente'))+selectField('Moto *','stockId',stockOptions(s.stockId))+field('Precio final de venta · USD *','amount','number',s.amount,false,true)+field('Fecha de venta','date','date',s.date)+field('Comisión · USD, opcional','commission','number',s.commission)+selectField('Origen de la venta','source',options(SOURCES,s.source))+selectField('Campaña que originó la venta','campaignId',options(db.campaigns.map(c=>[c.id,c.name]),s.campaignId,'Sin campaña atribuida'),true)+areaField('Observaciones','notes',s.notes),id);}
function editCampaign(id=''){const c=db.campaigns.find(c=>c.id===id)||{name:'',channel:'Facebook',date:today(),spend:'',consultations:0};formModal(id?'Editar campaña':'Registrar campaña','campaign',field('Nombre de la campaña *','name','text',c.name,true,true)+selectField('Canal','channel',options(['Facebook','Instagram','WhatsApp','Facebook e Instagram','Otro'],c.channel))+field('Fecha de referencia','date','date',c.date)+field('Inversión · USD','spend','number',c.spend)+field('Consultas recibidas','consultations','number',c.consultations),id);}
function submitRecord(form){const f=new FormData(form),get=name=>String(f.get(name)||'').trim(),id=form.dataset.id||uid(),type=form.dataset.form;let item;
 try{
  if(type==='client'){
   if(!get('name'))throw new Error('Ingresá el nombre del cliente.');const digits=get('phone').replace(/\D/g,'');if(get('phone')&&(digits.length<8||digits.length>15))throw new Error('Revisá el número de teléfono.');
   const old=client(id);item={...(old||{}),id,name:get('name'),phone:get('phone'),stockId:get('stockId'),stage:get('stage'),source:get('source'),paymentMode:get('paymentMode'),nextFollow:get('nextFollow'),notes:get('notes'),archived:old?.archived||false,createdAt:old?.createdAt||new Date().toISOString(),history:old?clone(old.history):[]};eventFor(item,old?'Ficha actualizada':'Cliente registrado');if(upsert('clients',item,'Cliente guardado'))$('modal').close();
  }else if(type==='stock'){
   if(!get('label'))throw new Error('Ingresá el nombre del modelo.');const price=get('price')===''?null:Number(get('price')),quantity=get('quantity')===''?null:Number(get('quantity'));if(price!==null&&(!Number.isFinite(price)||price<=0))throw new Error('El precio debe ser mayor que cero o quedar vacío.');if(quantity!==null&&(!Number.isInteger(quantity)||quantity<0))throw new Error('Las existencias deben ser unidades enteras o quedar vacías.');
   item={id,label:get('label'),type:get('type'),year:get('year'),colors:get('colors'),calcModelId:get('calcModelId'),price,quantity,promo:get('promo'),active:f.has('active')};if(upsert('stock',item,'Modelo actualizado'))$('modal').close();
  }else if(type==='request'){
   if(!client(get('clientId')))throw new Error('Seleccioná al cliente.');if(!get('date'))throw new Error('Ingresá la fecha de gestión.');const old=db.requests.find(r=>r.id===id),docs=(old?.docs||[]).map((d,i)=>({...d,done:f.has('doc-'+i)}));for(const label of get('newDocs').split('\n').map(x=>x.trim()).filter(Boolean)){if(label.length>150)throw new Error('Cada documento debe tener hasta 150 caracteres.');if(!docs.some(d=>d.label.toLowerCase()===label.toLowerCase()))docs.push({label,done:false});}
   item={id,clientId:get('clientId'),lender:get('lender'),status:get('status'),date:get('date'),expires:get('expires'),notes:get('notes'),docs};const next=clone(db),i=next.requests.findIndex(x=>x.id===id);i<0?next.requests.push(item):next.requests[i]=item;const c=next.clients.find(c=>c.id===item.clientId);eventFor(c,item.lender+': '+item.status);if(commit(next,'Solicitud guardada'))$('modal').close();
  }else if(type==='postsale'){
   if(!client(get('clientId')))throw new Error('Seleccioná al cliente.');if(!get('delivery'))throw new Error('Ingresá la fecha de entrega.');item={id,clientId:get('clientId'),stockId:get('stockId'),delivery:get('delivery'),nextDate:get('nextDate'),notes:get('notes'),done:f.has('done')};if(upsert('postSales',item,'Seguimiento guardado'))$('modal').close();
  }else if(type==='sale'){
   if(!client(get('clientId'))||!stock(get('stockId')))throw new Error('Seleccioná cliente y moto.');const amount=Number(get('amount')),commission=Number(get('commission')||0);if(!Number.isFinite(amount)||amount<=0||!Number.isFinite(commission)||commission<0)throw new Error('Revisá el precio de venta y la comisión.');if(!get('date'))throw new Error('Ingresá la fecha de venta.');
   item={id,clientId:get('clientId'),stockId:get('stockId'),amount,commission,date:get('date'),source:get('source'),campaignId:get('campaignId'),notes:get('notes')};const next=clone(db),i=next.sales.findIndex(x=>x.id===id);i<0?next.sales.push(item):next.sales[i]=item;const c=next.clients.find(c=>c.id===item.clientId);c.stage='Vendido';c.nextFollow='';eventFor(c,(i<0?'Venta registrada':'Venta actualizada')+' · '+money(amount));if(commit(next,'Venta guardada'))$('modal').close();
  }else if(type==='campaign'){
   if(!get('name')||!get('date'))throw new Error('Ingresá nombre y fecha de la campaña.');const spend=Number(get('spend')),consultations=Number(get('consultations'));if(!Number.isFinite(spend)||spend<0||!Number.isInteger(consultations)||consultations<0)throw new Error('Revisá la inversión y el número de consultas.');item={id,name:get('name'),channel:get('channel'),date:get('date'),spend,consultations};if(upsert('campaigns',item,'Campaña guardada'))$('modal').close();
  }else if(type==='settings'){
   const next=clone(db),validDays=Number(get('validDays'));if(!get('advisor')||!get('agency')||!Number.isInteger(validDays)||validDays<1||validDays>365)throw new Error('Completá asesor, agencia y una validez entre 1 y 365 días.');next.settings={advisor:get('advisor'),agency:get('agency'),phone:get('phone'),location:get('location'),validDays,theme:get('theme')};commit(next,'Ajustes guardados');
  }else if(type==='followup'){
   const next=clone(db),c=next.clients.find(c=>c.id===form.dataset.id);c.nextFollow=get('nextFollow');if(c.nextFollow&&c.nextFollow<=today())throw new Error('Elegí un próximo contacto posterior a hoy o dejalo vacío.');eventFor(c,'Contacto realizado'+(get('result')?': '+get('result'):''));if(commit(next,'Contacto registrado'))viewClient(c.id);
  }
 }catch(err){formError(err.message);}
}
function download(filename,content,type='application/octet-stream'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;($('modal').open?$('modal'):document.body).append(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url);},60000);}
function exportJSON(){download((demo?'Ejemplo-':'')+'Respaldo-Panel-TVS-'+today()+'.json',JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Respaldo descargado con tus registros.');}
function exportCSV(kind){const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const data=kind==='clients'?[['Nombre','Telefono','Modelo','Estado','Origen','Modalidad','Proximo contacto','Notas'],...db.clients.map(c=>[c.name,c.phone,stock(c.stockId)?.label,c.stage,c.source,c.paymentMode,c.nextFollow,c.notes])]:[['Cliente','Modelo','Fecha','Precio venta USD','Comision USD','Origen','Campaña'],...db.sales.map(s=>[client(s.clientId)?.name,stock(s.stockId)?.label,s.date,s.amount,s.commission,s.source,db.campaigns.find(c=>c.id===s.campaignId)?.name||''])];download((kind==='clients'?'Clientes':'Ventas')+'-TVS-'+today()+'.csv','\uFEFF'+data.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
async function copyText(text){try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(text);toast('Texto copiado.');}catch{openModal('Copiá tu mensaje',`<p class="subtext" style="margin-bottom:15px">Seleccioná el texto y presioná Ctrl+C.</p><textarea id="manual-copy" style="min-height:270px" readonly aria-label="Texto para copiar">${esc(text)}</textarea>`,`<button class="btn btn-primary" data-close>Listo</button>`);$('manual-copy').focus();$('manual-copy').select();}}
function openWhatsApp(c,text){let phone=(c?.phone||'').replace(/\D/g,'');if(phone.length===8)phone='503'+phone;if(phone.length<8){toast('Agregá el teléfono del cliente para abrir WhatsApp.',true);return;}if(/\[[^\]]+\]/.test(text)){toast('Completá los campos entre corchetes antes de abrir WhatsApp.',true);return;}window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}
function demoDB(){const d=freshDB(),now=today();d.clients=[{id:'ejemplo-ana',name:'Ana López · ejemplo',phone:'',stockId:'moto-apache-160-2v-ref',stage:'En evaluación',source:'Facebook',paymentMode:'Crédito',nextFollow:now,notes:'Datos ficticios para explorar el panel.',archived:false,createdAt:new Date().toISOString(),history:[{at:now,text:'Ejemplo: documentación recibida; pendiente de respuesta.'}]},{id:'ejemplo-carlos',name:'Carlos Pérez · ejemplo',phone:'',stockId:'moto-raider-125',stage:'Contactado',source:'WhatsApp',paymentMode:'Crédito',nextFollow:addDays(now,-1),notes:'Consultar la opción de financiamiento. Ejemplo ficticio.',archived:false,createdAt:new Date().toISOString(),history:[{at:now,text:'Ejemplo: consulta inicial.'}]},{id:'ejemplo-luis',name:'Luis Hernández · ejemplo',phone:'',stockId:'moto-sport-100',stage:'Vendido',source:'Facebook',paymentMode:'Contado',nextFollow:'',notes:'Venta ficticia de demostración.',archived:false,createdAt:new Date().toISOString(),history:[{at:now,text:'Ejemplo: moto entregada.'}]}];d.stock.find(s=>s.id==='moto-apache-160-2v-ref').price=2199;d.stock.find(s=>s.id==='moto-raider-125').price=1999;d.stock.find(s=>s.id==='moto-sport-100').price=1099;for(const s of d.stock.filter(s=>s.price!==null)){s.quantity=2;s.promo='Precio ficticio de demostración; no es una oferta vigente.';}
 d.campaigns=[{id:'ejemplo-pauta',name:'Campaña Sport · ejemplo',channel:'Facebook',date:now,spend:6,consultations:12}];d.sales=[{id:'ejemplo-venta',clientId:'ejemplo-luis',stockId:'moto-sport-100',amount:1099,commission:0,date:now,source:'Facebook',campaignId:'ejemplo-pauta',notes:'Venta ficticia.'}];d.requests=[{id:'ejemplo-solicitud',clientId:'ejemplo-ana',lender:'Crediopciones',status:'Enviada',date:now,expires:addDays(now,7),notes:'Solicitud ficticia de demostración.',docs:[{label:'Documento de identidad',done:true},{label:'Comprobante de ingresos',done:false}]}];d.postSales=[{id:'ejemplo-posventa',clientId:'ejemplo-luis',stockId:'moto-sport-100',delivery:now,nextDate:addDays(now,7),notes:'Confirmar cómo le ha ido después de la entrega. Ejemplo.',done:false}];return d;}
function switchDemo(on){if($('modal').open)$('modal').close();demo=on;storageBroken=false;db=loadDB();if(on&&!db.clients.length){const next=demoDB();commit(next,'Demostración lista. Los datos son ficticios.',true);}ui.quoteClientId='';ui.quoteStockId='';ui.quoteNote='';ui.cashPrice='';ui.messageClientId='';if(api)api.apply({model:'',price:'',down:'0'});applyTheme();navigate('resumen');render();if(!on)toast('Volviste a tus datos.');}
function importPrompt(incoming,source='archivo'){validateDB(incoming);openModal('Restaurar respaldo',`<p>El respaldo contiene <strong>${incoming.clients.length} clientes</strong>, <strong>${incoming.quotes.length} cotizaciones</strong> y <strong>${incoming.sales.length} ventas</strong>.</p><p class="subtext">Se reemplazarán los registros de ${demo?'la demostración':'este panel'}. Antes de restaurar, descargá una copia de los datos actuales.</p><div class="row-actions" style="margin-top:20px"><button class="btn" id="backup-before-restore">1. Descargar copia actual</button><button class="btn btn-primary" id="confirm-restore" disabled>2. Restaurar respaldo</button></div>`);$('backup-before-restore').onclick=()=>{if(storageBroken&&rawBroken)download('Datos-panel-anteriores-'+today()+'.json',rawBroken,'application/json');else exportJSON();$('confirm-restore').disabled=false;};$('confirm-restore').onclick=()=>{if(commit(clone(incoming),'Respaldo restaurado.',true)){$('modal').close();ui.quoteClientId='';ui.quoteStockId='';ui.messageClientId='';render();}};}
function navigate(route){if(!NAV.some(n=>n[0]===route))route='resumen';ui.route=route;if(location.hash!=='#'+route)location.hash=route;render();$('sidebar').classList.remove('open');$('sidebar-shade').hidden=true;window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('submit',e=>{if(e.target.matches('[data-form]')){e.preventDefault();submitRecord(e.target);}});
document.addEventListener('click',async e=>{
 if(e.target.closest('[data-close]')){$('modal').close();return;}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id||'',action=b.dataset.action;
 if(action==='delete-client')confirmDeleteClient(id);else if(action==='confirm-delete-client')deleteClientConfirmed(id,b.dataset.revision);else if(action==='restore-included-backup')importPrompt(clone(INITIAL_BACKUP),'respaldo incluido');else if(action==='quick-lead')openQuickLead();else if(action==='new-client')editClient();else if(action==='edit-client')editClient(id);else if(action==='view-client')viewClient(id);
 else if(action==='archive-client'){const next=clone(db),c=next.clients.find(c=>c.id===id);c.archived=!c.archived;eventFor(c,c.archived?'Cliente archivado':'Cliente reactivado');if(commit(next,c.archived?'Cliente archivado. Podés reactivarlo desde el filtro Archivados.':'Cliente reactivado.'))$('modal').close();}
 else if(action==='quote-client'){const c=client(id);ui.quoteClientId=id;ui.quoteMode=c.paymentMode==='Contado'?'cash':'credit';if($('modal').open)$('modal').close();navigate('cotizar');if(c.stockId)chooseQuoteStock(c.stockId);if(c.price!==null&&c.price!==undefined){ui.cashPrice=c.price;if(api)api.apply({price:String(c.price)});if(ui.quoteMode==='cash')renderCash();}}
 else if(action==='client-message'){ui.messageClientId=id;if($('modal').open)$('modal').close();navigate('mensajes');}
 else if(action==='go-quote')navigate('cotizar');else if(action==='save-quote')saveQuote();
 else if(action==='view-quote')viewQuote(id);else if(action==='copy-quote')await copyText(quoteMessage(db.quotes.find(q=>q.id===id)));
 else if(action==='print-quote'){const q=db.quotes.find(q=>q.id===id);$('print-area').innerHTML=quoteHTML(q);window.print();}
 else if(action==='download-pdf'){const q=db.quotes.find(q=>q.id===id);b.disabled=true;try{download(q.number+'.pdf',await makePDF(q));}catch(err){toast('No se pudo generar el PDF. Podés usar Imprimir y Guardar como PDF.',true);}finally{b.disabled=false;}}
 else if(action==='requote'){const q=db.quotes.find(q=>q.id===id);ui.quoteClientId=q.clientId;ui.quoteStockId=q.stockId;ui.quoteNote=q.note;ui.quoteMode=q.mode;ui.cashPrice=q.price;if(q.mode==='cash')restoreCashDraft(q);ui.quoteValidUntil=addDays(today(),db.settings.validDays);$('modal').close();navigate('cotizar');if(q.calcState&&api)api.apply(q.calcState);}
 else if(action==='cash-mode'||action==='credit-mode'){ui.quoteMode=action==='cash-mode'?'cash':'credit';renderCalculator();onCalculatorChange();}
 else if(action==='select-sheet'){ui.sheetId=id;renderTechnicalSheets();}
 else if(action==='copy-sheet')await copyTechnicalSheet(id,b);
 else if(action==='download-sheet')downloadTechnicalSheet(id);
 else if(action==='preview-sheet'){const sheet=technicalSheet(id);if(sheet)showTechnicalSheet(sheet);}
 else if(action==='new-stock')editStock();else if(action==='edit-stock')editStock(id);else if(action==='quote-stock'){navigate('cotizar');chooseQuoteStock(id);}
 else if(action==='new-request')editRequest();else if(action==='edit-request')editRequest(id);else if(action==='request-client')editRequest('',id);
 else if(action==='new-postsale')editPostSale();else if(action==='edit-postsale')editPostSale(id);else if(action==='complete-postsale'){const p=clone(db.postSales.find(p=>p.id===id));p.done=true;upsert('postSales',p,'Seguimiento marcado como realizado.');}
 else if(action==='new-sale')editSale();else if(action==='sale-client')editSale('',id);else if(action==='edit-sale')editSale(id);else if(action==='new-campaign')editCampaign();else if(action==='edit-campaign')editCampaign(id);
 else if(action==='choose-template'){ui.template=id;renderMessages();}else if(action==='copy-message')await copyText($('message-text').value);else if(action==='open-whatsapp')openWhatsApp(client(ui.messageClientId),$('message-text').value);
 else if(action==='export-json')exportJSON();else if(action==='export-clients')exportCSV('clients');else if(action==='export-sales')exportCSV('sales');else if(action==='export-raw')download('Datos-anteriores-'+today()+'.json',rawBroken,'application/json');else if(action==='import-json'){$('restore-file').value='';$('restore-file').click();}
 else if(action==='recover-previous'){try{const raw=localStorage.getItem(key()+'.anterior');if(!raw)throw new Error('Todavía no hay un guardado anterior para recuperar.');importPrompt(JSON.parse(raw),'anterior');}catch(err){toast(err.message,true);}}
 else if(action==='enter-demo')switchDemo(true);else if(action==='exit-demo')switchDemo(false);
});
function preserveInput(id,fn){const old=$(id),start=old?.selectionStart,end=old?.selectionEnd;fn();const next=$(id);if(next){next.focus();if(start!==null&&start!==undefined)next.setSelectionRange(start,end);}}
document.addEventListener('input',e=>{const t=e.target;if(t.id==='client-search'){ui.clientSearch=t.value;preserveInput(t.id,renderClients);}else if(t.id==='quote-search'){ui.quoteSearch=t.value;preserveInput(t.id,renderQuotes);}else if(t.id==='sheet-search'){ui.sheetSearch=t.value;preserveInput(t.id,renderTechnicalSheets);}else if(t.id==='quote-note')ui.quoteNote=t.value;else if(t.id==='cash-price')ui.cashPrice=t.value;});
document.addEventListener('change',e=>{const t=e.target,filters={'client-stage-filter':['clientStage',renderClients],'client-archive-filter':['clientArchive',renderClients],'quote-status-filter':['quoteStatus',renderQuotes],'stock-type-filter':['stockType',renderStock],'request-status-filter':['requestStatus',renderRequests],'report-month':['reportMonth',renderReports]};if(filters[t.id]){const [k,fn]=filters[t.id];ui[k]=t.value;fn();}else if(t.id==='quote-client')ui.quoteClientId=t.value;else if(t.id==='quote-stock')chooseQuoteStock(t.value);else if(t.id==='quote-valid-until')ui.quoteValidUntil=t.value;else if(t.id==='message-client'){ui.messageClientId=t.value;renderMessages();}else if(t.id==='saved-quote-status'){const q=clone(db.quotes.find(q=>q.id===t.dataset.id));q.status=t.value;upsert('quotes',q,'Estado actualizado.');}});
$('restore-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>30*1024*1024)throw new Error('El respaldo supera el tamaño admitido de 30 MB.');importPrompt(JSON.parse(await file.text()));}catch(err){toast(err.message,true);}});
$('menu-toggle').onclick=()=>{$('sidebar').classList.toggle('open');$('sidebar-shade').hidden=!$('sidebar').classList.contains('open');};$('sidebar-shade').onclick=()=>{$('sidebar').classList.remove('open');$('sidebar-shade').hidden=true;};
$('theme-toggle').onclick=()=>{const next=clone(db);next.settings.theme=next.settings.theme==='dark'?'light':'dark';commit(next,'Apariencia guardada.');};
window.addEventListener('hashchange',()=>{ui.route=location.hash.slice(1)||'resumen';navigate(ui.route);});
window.addEventListener('storage',e=>{if(e.key===key()){db=loadDB();applyTheme();render();toast('Se actualizaron los datos desde otra pestaña.');}});
window.addEventListener('message',e=>{if(e.source!==$('calculator').contentWindow)return;if(e.data?.type==='tvs-calc-image-fallback'){showCalculatorImage(e.data.blob,e.data.filename);return;}if(e.data?.type==='tvs-calc-ready'){api=$('calculator').contentWindow.TVSCalculator;models=api.models();logo=api.logo();api.setTheme(db.settings.theme);if(ui.route==='inventario'||ui.route==='resumen')render();onCalculatorChange();}if(e.data?.type==='tvs-calc-change'){if(!api)api=$('calculator').contentWindow.TVSCalculator;onCalculatorChange();}if(e.data?.type==='tvs-calc-save')saveQuote();if(e.data?.type==='tvs-calc-height'&&Number.isFinite(e.data.height))$('calculator').style.height=Math.max(700,Math.min(6000,e.data.height))+'px';});
async function preparePDFLink(q){const generation=pdfGeneration;try{const blob=await makePDF(q),link=$('pdf-download-link');if(generation!==pdfGeneration||!link||!$('modal').open)return;if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(blob);link.href=pdfUrl;link.download=q.number+'.pdf';link.removeAttribute('aria-disabled');link.style.pointerEvents='';link.innerHTML=icon('download')+'Descargar PDF';}catch(err){const link=$('pdf-download-link');if(link){link.textContent='Usá Imprimir / PDF';link.classList.remove('btn-primary');}}}
async function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src;});}
async function makePDF(q){
 const W=1240,H=1754,pad=94,maxW=W-pad*2;const pages=[];let canvas,ctx,y;
 function newPage(){if(canvas)pages.push(canvas);canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.textBaseline='top';y=pad;}
 function line(text,size=20,color='#16243b',weight=400,max=maxW){
  const font=()=>{ctx.font=`${weight} ${size}px Arial,sans-serif`;ctx.fillStyle=color;};
  const paint=row=>{if(y+size*1.6>H-pad)newPage();font();ctx.fillText(row,pad,y);y+=size*1.55;};
  for(const paragraph of String(text||'').split('\n')){let row='';font();for(let word of paragraph.split(/\s+/)){font();if(row&&ctx.measureText(row+' '+word).width>max){paint(row);row='';}while(ctx.measureText(word).width>max){let cut=Math.max(1,Math.floor(word.length*max/ctx.measureText(word).width));while(cut>1&&ctx.measureText(word.slice(0,cut)).width>max)cut--;paint(word.slice(0,cut));word=word.slice(cut);font();}row+=(row?' ':'')+word;}paint(row);}
 }

 newPage();ctx.fillStyle='#214d80';ctx.fillRect(pad,y+72,maxW,3);line('Cotización '+(q.mode==='cash'?'de contado':'de crédito'),34,'#16243b',600,maxW-250);line(q.number+' · '+fmtDate(q.date),16,'#748096');
 if(logo){try{const im=await loadImage(logo);ctx.drawImage(im,W-pad-175,pad+5,175,175*im.height/im.width);}catch{}}
 y=pad+112;line('PREPARADA PARA',14,'#748096',500);line(q.customerName||'Cliente',24,'#16243b',600);if(q.customerPhone)line(q.customerPhone,18,'#748096');line('Válida hasta: '+fmtDate(q.validUntil),17,'#748096');y+=16;
 const photo=photoForQuote(q);if(photo){try{const im=await loadImage(photo),h=225,w=im.width/im.height*h;ctx.drawImage(im,pad+(maxW-w)/2,y,w,h);y+=h+18;}catch{}}
 line('TVS '+q.modelLabel,27,'#16243b',600);line(quotePlan(q),18,'#748096');y+=20;
 ctx.fillStyle='#edf3fc';ctx.fillRect(pad,y,maxW,99);ctx.fillStyle='#214d80';ctx.font='20px Arial';ctx.fillText(q.mode==='cash'?'Precio de contado':q.calculation.selected.months+' cuotas mensuales de',pad+25,y+22);ctx.font='600 43px Arial';const payment=money(q.mode==='cash'?q.price:q.calculation.selected.monthly);ctx.fillText(payment,W-pad-25-ctx.measureText(payment).width,y+23);y+=126;
 for(const [label,value]of quoteEntries(q)){if(y+55>H-pad)newPage();ctx.font='20px Arial';ctx.fillStyle='#66758b';ctx.fillText(label,pad,y);ctx.fillStyle='#16243b';ctx.font='500 21px Arial';ctx.fillText(value,W-pad-ctx.measureText(value).width,y);y+=43;ctx.fillStyle='#e5e9f0';ctx.fillRect(pad,y-10,maxW,1);}
 y+=15;line(quoteConditions(q),16,'#66758b');y+=20;line(q.advisor+' · '+q.agency,18,'#214d80',600);line([q.advisorPhone,q.location].filter(Boolean).join(' · '),16,'#748096');pages.push(canvas);
 const encoder=new TextEncoder(),chunks=[],offsets=[0];let pos=0;const add=v=>{const b=typeof v==='string'?encoder.encode(v):v;chunks.push(b);pos+=b.length;};const count=2+pages.length*3;const object=(id,content)=>{offsets[id]=pos;add(id+' 0 obj\n');add(content);add('\nendobj\n');};add('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Kids ['+pages.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] /Count '+pages.length+' >>');
 for(let i=0;i<pages.length;i++){const p=pages[i],base=3+i*3,binary=atob(p.toDataURL('image/jpeg',.92).split(',')[1]),jpg=Uint8Array.from(binary,c=>c.charCodeAt(0));object(base,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 '+(base+1)+' 0 R >> >> /Contents '+(base+2)+' 0 R >>');offsets[base+1]=pos;add((base+1)+' 0 obj\n<< /Type /XObject /Subtype /Image /Width '+W+' /Height '+H+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+jpg.length+' >>\nstream\n');add(jpg);add('\nendstream\nendobj\n');const stream='q\n595.28 0 0 841.89 0 0 cm\n/Im0 Do\nQ\n';object(base+2,'<< /Length '+encoder.encode(stream).length+' >>\nstream\n'+stream+'endstream');}
 const xref=pos;add('xref\n0 '+(count+1)+'\n0000000000 65535 f \n');for(let i=1;i<=count;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add('trailer\n<< /Size '+(count+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF');return new Blob(chunks,{type:'application/pdf'});
}
